import{_ as e,o as t,c as n,a2 as i}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Weapons and damage families","description":"","frontmatter":{},"headers":[],"relativePath":"game-design/combat/weapons-and-damage.md","filePath":"game-design/combat/weapons-and-damage.md"}'),o={name:"game-design/combat/weapons-and-damage.md"};function r(s,a,d,l,m,c){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="weapons-and-damage-families" tabindex="-1">Weapons and damage families <a class="header-anchor" href="#weapons-and-damage-families" aria-label="Permalink to &quot;Weapons and damage families&quot;">​</a></h1><p><strong>Design status: Proposed weapon identities and expanded injury interactions; Accepted global/local separation remains unchanged. Implementation: no new weapon-family mechanics established by this integration.</strong></p><p><a href="/Syrolands-Public/guide/combat/weapons-and-damage.html">Player guide</a> · <a href="/Syrolands-Public/game-design/combat/overview.html">Combat foundations</a></p><h2 id="behavior-before-damage-totals" tabindex="-1">Behavior before damage totals <a class="header-anchor" href="#behavior-before-damage-totals" aria-label="Permalink to &quot;Behavior before damage totals&quot;">​</a></h2><p>Weapon design determines the tactical problem an attack presents. Craft quality determines how efficiently and consistently that design performs. Cutting/slashing, piercing/puncture and blunt/impact are candidate physical injury families, not a new implemented damage enum or a conversion table for legacy damage types. A weapon can support more than one attack type; the attack being attempted matters as well as the item.</p><table tabindex="0"><thead><tr><th>Weapon</th><th>Proposed identity</th><th>Questions left open</th></tr></thead><tbody><tr><td>Dagger</td><td>Precise puncture and short openings, low raw impact</td><td>Reach and protection against repeated precision attacks</td></tr><tr><td>Sword</td><td>Versatile cutting and thrust capability</td><td>Attack selection, commitment and recovery</td></tr><tr><td>Warhammer / mace</td><td>Blunt impact, deformation and fracture potential; costly misses</td><td>Trauma transmitted through armor and control costs</td></tr><tr><td>Spear</td><td>Thrust, penetration, reach and positional control</td><td>Close-range constraints and armor interaction</td></tr><tr><td>Axe</td><td>Cutting and structural impact with high commitment</td><td>Equipment damage versus bodily injury</td></tr></tbody></table><p>These are directions, not guaranteed wounds or final balance. More damage per second is not the sole progression axis. One-handed weapons with shields and two-handed weapons should pose different decisions. <a href="/Syrolands-Public/game-design/combat/future-directions.html">Bounded impact propagation</a> remains separate Proposed work; a two-handed item does not automatically receive cleave or additional full hits.</p><h2 id="injury-and-mitigation-boundary" tabindex="-1">Injury and mitigation boundary <a class="header-anchor" href="#injury-and-mitigation-boundary" aria-label="Permalink to &quot;Injury and mitigation boundary&quot;">​</a></h2><p>The actual primary region receives the accepted experimental <a href="/Syrolands-Public/game-design/combat/damage.html">Local Trauma policy</a>. Cutting does not currently install bleeding, piercing does not bypass armor by definition, and blunt impact does not install fractures. Future family-specific injury or armor calculations must be reconciled with that policy before implementation. Neck/head attacks are not random instant-kill buttons.</p><p><a href="/Syrolands-Public/game-design/combat/armor-and-mitigation.html">Armor and mitigation</a> owns protection and condition interactions. <a href="/Syrolands-Public/game-design/combat/stamina-and-reactive-combat.html">Stamina and recovery</a> owns proposed commitment and pacing. Ranged aimed shots remain unresolved; the current localized melee fixture does not establish their support.</p><h2 id="quality-and-professions" tabindex="-1">Quality and professions <a class="header-anchor" href="#quality-and-professions" aria-label="Permalink to &quot;Quality and professions&quot;">​</a></h2><p>The five canonical quality dimensions—Offensive Efficiency, Handling, Precision/Consistency, Integrity and Functional Retention—are defined only in <a href="/Syrolands-Public/game-design/items/itemization-and-craft-quality.html#weapon-quality-dimensions">Itemization &amp; Craft Quality</a>. Quality does not turn an axe into a spear or grant universal penetration. Special traits, thresholds and latent properties require explicit interaction rules; they do not supersede residual ×2 trauma.</p><p><a href="/Syrolands-Public/game-design/professions/blacksmithing.html">Blacksmithing</a> covers proposed metal equipment expertise; <a href="/Syrolands-Public/game-design/professions/carpentry.html#bowmaking-and-fletching">Carpentry / Bowmaking</a> covers relevant bow construction. Maintenance supports the accepted <a href="/Syrolands-Public/game-design/equipment-and-loot.html">replaceability and meaningful-loss economy</a>. Masterworks do not grant insurance or permanent retention.</p><h2 id="related-design" tabindex="-1">Related design <a class="header-anchor" href="#related-design" aria-label="Permalink to &quot;Related design&quot;">​</a></h2><p><a href="/Syrolands-Public/game-design/combat/status-and-open-questions.html">Status and unresolved decisions</a></p>',15)])])}const h=e(o,[["render",r]]);export{u as __pageData,h as default};
